# Reborn: plan first; archive complete obsolete workspaces/artifacts with verified hashes before deleting only resolved generated directories.
[CmdletBinding()]
param([switch]$Apply)
$ErrorActionPreference='Stop'
if($PSVersionTable.PSVersion.Major-lt 7){throw 'PowerShell 7 is required.'}
$repo=[IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot));$workspace=Split-Path -Parent $repo;$artifacts=Join-Path $repo 'artifacts'
#-------------------------------------------------------------------------------------------------
<# Reborn: only direct old SDK siblings with provenance markers or artifact children qualify; never sources, the workspace root, reference SDK or game data. #>
#-------------------------------------------------------------------------------------------------
function Assert-LegacyTarget([string]$Path){$pathFull=[IO.Path]::GetFullPath($Path);$parent=Split-Path -Parent $pathFull;$name=Split-Path -Leaf $pathFull;if(-not(($parent-ieq $artifacts) -or ($parent-ieq $workspace -and $name-match '^Uprising(Alpha|Overlay)[A-Za-z0-9_-]+$' -and ((Test-Path -LiteralPath (Join-Path $pathFull 'workspace-preparation.json')) -or (Test-Path -LiteralPath (Join-Path $pathFull 'overlay-manifest.json')))))){throw 'Cleanup target is outside the explicitly generated scope.'};for($item=Get-Item -LiteralPath $pathFull;$null-ne $item;$item=$item.Parent){if(($item.Attributes-band [IO.FileAttributes]::ReparsePoint)-ne 0){throw 'Redirected cleanup target refused.'}}}
Write-Host 'Reborn: scanning live code references before selecting cleanup targets.'
$codeFiles=@(& git -C $repo ls-files scripts source tests alpha);$code=[Text.StringBuilder]::new();foreach($relative in $codeFiles){if([IO.Path]::GetExtension($relative)-in @('.ps1','.cs','.json','.xml','.csproj')){[void]$code.AppendLine([IO.File]::ReadAllText((Join-Path $repo $relative)))}};$references=$code.ToString()
$keep=@('ConscriptAuthoredTrials-a','Conscript-Sku-20261018-a','ConscriptLaunch-970ba463f81a43b3b06730ee4d68a3d0','LegacyLaunches');$targets=[Collections.Generic.List[object]]::new();$retained=[Collections.Generic.List[object]]::new()
foreach($dir in Get-ChildItem -LiteralPath $workspace -Directory){if($dir.Name-match '^Uprising(Alpha|Overlay)[A-Za-z0-9_-]+$' -and ((Test-Path -LiteralPath (Join-Path $dir.FullName 'workspace-preparation.json')) -or (Test-Path -LiteralPath (Join-Path $dir.FullName 'overlay-manifest.json')))){$targets.Add($dir)}}
Write-Host 'Reborn: selecting unreferenced artifact directories.'
foreach($dir in Get-ChildItem -LiteralPath $artifacts -Directory){
    if($dir.Name-in $keep -or $references.IndexOf($dir.Name,[StringComparison]::OrdinalIgnoreCase)-ge 0){$retained.Add([pscustomobject]@{Path=$dir.FullName;Reason='Referenced by live code/test or explicitly retained gameplay/source evidence'});continue}
    if(@([IO.Directory]::EnumerateFiles($dir.FullName,'*.etl',[IO.SearchOption]::AllDirectories)).Count -or @([IO.Directory]::EnumerateFiles($dir.FullName,'*.dmp',[IO.SearchOption]::AllDirectories)).Count){$retained.Add([pscustomobject]@{Path=$dir.FullName;Reason='Original runtime trace/minidump retained'});continue};$targets.Add($dir)
}
# Reborn: never remove an old workspace while a Studio process is running from it; no process is stopped.
foreach($process in @(Get-Process EALAModStudio -ErrorAction SilentlyContinue)){if(-not $process.Path){throw 'Cannot resolve active Studio location; defer cleanup.'};foreach($dir in @($targets.ToArray())){if($process.Path.StartsWith($dir.FullName+'\',[StringComparison]::OrdinalIgnoreCase)){$null=$targets.Remove($dir);$retained.Add([pscustomobject]@{Path=$dir.FullName;Reason='Active Studio workspace'})}}}
Write-Host ('Reborn: inventorying '+$targets.Count+' generated target directories.')
$files=[Collections.Generic.List[object]]::new();foreach($dir in $targets){Assert-LegacyTarget $dir.FullName;foreach($item in Get-ChildItem -LiteralPath $dir.FullName -Recurse -Force){if(($item.Attributes-band [IO.FileAttributes]::ReparsePoint)-ne 0){throw 'Redirected generated tree retained; no cleanup performed.'};if(-not $item.PSIsContainer){$files.Add([pscustomobject]@{Path=$item.FullName;Relative=[IO.Path]::GetRelativePath($workspace,$item.FullName).Replace('\','/');Length=$item.Length;LastWriteUtcTicks=$item.LastWriteTimeUtc.Ticks;Sha256=$null})}}}
$summary=[pscustomobject]@{Apply=[bool]$Apply;Targets=@($targets|ForEach-Object FullName);FileCount=$files.Count;OriginalBytes=($files|Measure-Object Length -Sum).Sum;Retained=$retained.ToArray();SourceReferencesProtected=$true;GameExecuted=$false}
if(-not $Apply){$summary;return}
# Reborn: retain exact old gameplay candidates at short repository-local paths used by the historical launch script; do not substitute freshly built packages.
$legacy=@(
    @('Cannon','UprisingAlpha-20261011-h/builtmods/RebornAlphaInput-827c7fe6f81d44bdb39aed9e5d73f46c/build/package','40C09781BAB82643FBBC6DF5A8DFA674B74BF16B8B93F4A5B605FF5778F0BE7F'),
    @('Soviet','UprisingAlpha-20261012-a/builtmods/RebornAlphaInput-4cdaaed8530a4d5fa735fab8da5e37d9/build/package','0414E554AE9049631B163C508806F2A5EC2AE277030CE1A5DEE9374150C483BD'),
    @('Combined','UprisingAlpha-20261012-c/builtmods/RebornAlphaInput-c9d132f96e1049e689f1574c741ee126/build/package','826859F2CD92D840B37D0AABB239DF1C799F433A3A8014912F34757AEF5554E3'))
foreach($entry in $legacy){$destination=Join-Path $artifacts ('LegacyLaunches/'+$entry[0]);if(-not(Test-Path -LiteralPath $destination)){$source=Join-Path $workspace $entry[1];if((Get-FileHash -LiteralPath (Join-Path $source 'RebornArmorProbe.big') -Algorithm SHA256).Hash-cne $entry[2]){throw 'Historical gameplay archive changed; defer cleanup.'};$null=New-Item -ItemType Directory -Path $destination;foreach($file in Get-ChildItem -LiteralPath $source -File){Copy-Item -LiteralPath $file.FullName -Destination (Join-Path $destination $file.Name)}};if((Get-FileHash -LiteralPath (Join-Path $destination 'RebornArmorProbe.big') -Algorithm SHA256).Hash-cne $entry[2]){throw 'Historical gameplay preservation failed.'}}
$history=Join-Path $repo ('.maintenance/cleanup-'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,8));$null=New-Item -ItemType Directory -Path $history
$archive=Join-Path $history 'complete-experiments.zip';$output=[IO.File]::Open($archive,[IO.FileMode]::CreateNew);$zip=[IO.Compression.ZipArchive]::new($output,[IO.Compression.ZipArchiveMode]::Create,$false)
try{foreach($file in $files){$input=[IO.File]::Open($file.Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$file.Sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($input));$input.Position=0;$entry=$zip.CreateEntry($file.Relative,[IO.Compression.CompressionLevel]::Optimal);$stream=$entry.Open();try{$input.CopyTo($stream)}finally{$stream.Dispose()}}finally{$input.Dispose()}}}finally{$zip.Dispose();$output.Dispose()}
Write-Output ('Reborn: complete backup written; verifying '+$files.Count+' archived file hashes before any deletion.')
$input=[IO.File]::OpenRead($archive);$zip=[IO.Compression.ZipArchive]::new($input,[IO.Compression.ZipArchiveMode]::Read,$false)
try{if($zip.Entries.Count-ne $files.Count){throw 'Backup entry count differs.'};foreach($file in $files){$entry=$zip.GetEntry($file.Relative);if($null-eq $entry -or $entry.Length-ne $file.Length){throw 'Backup file geometry differs.'};$stream=$entry.Open();try{if([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($stream))-cne $file.Sha256){throw 'Backup content hash differs; no deletion permitted.'}}finally{$stream.Dispose()};$current=Get-Item -LiteralPath $file.Path;if($current.Length-ne $file.Length -or $current.LastWriteTimeUtc.Ticks-ne $file.LastWriteUtcTicks){throw 'Original changed during archival; no deletion permitted.'}}}finally{$zip.Dispose();$input.Dispose()}
[IO.File]::WriteAllText((Join-Path $history 'inventory.json'),([pscustomobject]@{Summary=$summary;Files=$files}|ConvertTo-Json -Depth 7))
foreach($dir in $targets){Assert-LegacyTarget $dir.FullName;$current=@(Get-ChildItem -LiteralPath $dir.FullName -Recurse -Force);foreach($item in $current){if(($item.Attributes-band [IO.FileAttributes]::ReparsePoint)-ne 0){throw 'Changed target retained.'}};if(@($current|Where-Object {-not $_.PSIsContainer}).Count-ne @($files|Where-Object {$_.Path.StartsWith($dir.FullName+'\',[StringComparison]::OrdinalIgnoreCase)}).Count){throw 'Target file inventory changed; retained.'};Remove-Item -LiteralPath $dir.FullName -Recurse -Force}
$result=[pscustomobject]@{RemovedDirectories=$targets.Count;RemovedFiles=$files.Count;OriginalBytes=$summary.OriginalBytes;ArchiveBytes=(Get-Item -LiteralPath $archive).Length;Archive=$archive;RecoveredBy='Extract complete-experiments.zip under the original workspace root; see inventory.json';RetainedDirectoryCount=$retained.Count};[IO.File]::WriteAllText((Join-Path $history 'result.json'),($result|ConvertTo-Json -Depth 5));$result
